#!/usr/bin/env python3
"""Copy generated Go UCD ranges, sequences and exact aliases into compiler-only C tables.

The code-point properties are cohere's unicodeproperties, which the Go provider
reads; the properties of strings are internal/unicodeproperties/tables.go's. No
Unicode download or second Unicode version is involved. The compiled C output
is compared entry for entry with unicodeproperties.Lookup by the native tests.
"""
import argparse
import ast
import hashlib
import json
import pathlib
import re
import zipfile

root = pathlib.Path(__file__).resolve().parents[3]
source = (root / "internal/unicodeproperties/tables.go").read_text()
cohere = root / "cohere/unicodeproperties"
cohere_source = (cohere / "tables_generated.go").read_text()
version = re.search(r'^const Version = "([0-9.]+)"$', cohere_source, re.M).group(1)
assert source.startswith("// Code generated by generate.go from Unicode " + version + ". "), "tables.go is not cohere's Unicode"
# cohere's tables are generated from its vendored UCD subset, whose files are unmodified.
ucd = zipfile.ZipFile(cohere / "internal/ucd" / (version + ".zip"))
output = ["// Generated by internal/regexp/testdata/generate-runtime-properties.py. Do not edit.",
          "// Unicode " + version + ", from cohere/unicodeproperties/tables_generated.go and internal/unicodeproperties/tables.go.",
          "// https://www.unicode.org/license.txt", "#ifndef ADAMIC_REGEXP_COMPILE_TABLES_H",
          "#define ADAMIC_REGEXP_COMPILE_TABLES_H"]
# Preserve the UCD input digests: the Go generator's for the strings, and cohere's subset for the rest.
digests = dict(re.findall(r"^// (\S+) SHA-256 ([0-9a-f]{64})$", source, re.M))
for entry in ucd.namelist():
    name, digest = entry.rsplit("/", 1)[-1], hashlib.sha256(ucd.read(entry)).hexdigest()
    assert digests.setdefault(name, digest) == digest, name + " differs between the two generators"
output[1:1] = ["// " + name + " SHA-256 " + digest for name, digest in sorted(digests.items())]

body = cohere_source.split("var properties = map[string]Property{\n", 1)[1].split("\n}\n", 1)[0]
pattern = r'\t"([^"\n]+)":\s*\{Family: "(\w+)", Ranges: \[\]Range\{(.*)\}\},'
rows = re.findall(pattern, body)
assert re.sub(pattern, "", body).strip() == "", "unparsed cohere property"
properties = {}
for identifier, _, ranges in rows:
    pairs = re.findall(r"\{0x([0-9a-f]+), 0x([0-9a-f]+)\}", ranges)
    assert re.sub(r"\{0x[0-9a-f]+, 0x[0-9a-f]+\}(, )?", "", ranges) == "", "unparsed range"
    properties[identifier] = [(int(a, 16), int(b, 16)) for a, b in pairs]
# Sets are numbered binary properties by name, then General_Category values and
# scripts in PropertyValueAliases.txt's order, each script's Script set before
# its Script_Extensions.
values = [[field.strip() for field in line.split("#")[0].split(";")]
          for line in ucd.read("PropertyValueAliases.txt").decode().splitlines()]
order = sorted(identifier for identifier in properties if "=" not in identifier)
order += ["gc=" + fields[1] for fields in values if fields[0] == "gc"]
for fields in values:
    if fields[0] == "sc" and "sc=" + fields[2] in properties:
        order += ["sc=" + fields[2], "scx=" + fields[2]]
assert sorted(order) == sorted(properties), "cohere's properties and their order differ"
number = {}
for index, identifier in enumerate(order):
    number[identifier] = str(index)
    ranges = ["{0x%04X,0x%04X}," % pair for pair in properties[identifier]]
    name = "regex_compile_ranges_" + str(index)
    if ranges:
        output.append("static const adamic_regex_compile_range " + name + "[] = {")
        output.extend(ranges)
        output.append("};")
    output.append("static const adamic_regex_compile_property regex_compile_property_" + str(index) +
                  " = {" + (name if ranges else "NULL") + "," + str(len(ranges)) + ",NULL,0,false};")

aliases = {}
body = cohere_source.split("var aliases = map[string]string{\n", 1)[1].split("\n}", 1)[0]
rows = re.findall(r'\t"([^"\n]+)":\s*"([^"\n]+)",', body)
assert re.sub(r'\t"([^"\n]+)":\s*"([^"\n]+)",', "", body).strip() == "", "unparsed cohere alias"
for alias, identifier in rows:
    aliases[alias] = "regex_compile_property_" + number[identifier]

body = source.split("var stringProperties = map[string][]string{", 1)[1].split("\n}", 1)[0]
rows = re.findall(r'"([^"\n]+)":\s*(\w+),', body)
assert re.sub(r'\s|"([^"\n]+)":\s*(\w+),', "", body) == "", "unparsed string alias"
for alias, variable in rows:
    sequences_body = source.split("var " + variable + " = []string{", 1)[1].split("\n}", 1)[0]
    sequences = []
    for line in sequences_body.splitlines():
        if line.strip():
            # Go quoted Unicode sequences use the same Unicode escapes as Python.
            sequences.append(ast.literal_eval(line.strip().removesuffix(",")))
    for index, text in enumerate(sequences):
        output.append("static const uint32_t regex_compile_" + variable + "_" + str(index) + "[] = {" +
                      ",".join(str(ord(c)) for c in text) + "};")
    output.append("static const adamic_regex_compile_text regex_compile_" + variable + "[] = {")
    output.extend("{regex_compile_" + variable + "_" + str(i) + "," + str(len(s)) + "}," for i, s in enumerate(sequences))
    output.append("};")
    name = "regex_compile_property_" + variable
    output.append("static const adamic_regex_compile_property " + name + " = {NULL,0,regex_compile_" +
                  variable + "," + str(len(sequences)) + ",true};")
    assert alias not in aliases
    aliases[alias] = name
output.append("typedef struct { const char *name; const adamic_regex_compile_property *property; } regex_compile_alias;")
output.append("static const regex_compile_alias regex_compile_aliases[] = {")
output.extend("{" + json.dumps(alias) + ",&" + name + "}," for alias, name in sorted(aliases.items()))
output.extend(["};", "#endif", ""])
parser = argparse.ArgumentParser()
parser.add_argument("--output", type=pathlib.Path, default=root / "internal/native/runtime/regexp_compile_tables.h")
args = parser.parse_args()
args.output.write_text("\n".join(output))
print(f"{len(order)} sets, {len(aliases)} aliases, {len(rows)} string properties")
